package com.payments.processing

import java.security.MessageDigest
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CountDownLatch
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

class PaymentProcessor(
    private val hmacSecret: ByteArray,
    private val shutdownLatch: CountDownLatch = CountDownLatch(1)
) {
    private val isShuttingDown = AtomicBoolean(false)
    private val activeTransactions = ConcurrentHashMap<String, TransactionState>()
    private val completedTokens = ConcurrentHashMap<String, Long>()

    data class TransactionState(
        val merchantId: String,
        val amount: Long,
        val timestamp: Long,
        val status: String = "PENDING"
    )

    data class PaymentRequest(
        val merchantId: String,
        val amount: Long,
        val nonce: String,
        val authToken: String
    )

    data class PaymentResult(
        val success: Boolean,
        val transactionId: String? = null,
        val error: String? = null
    )

    fun initiateGracefulShutdown() {
        isShuttingDown.set(true)
        // Wait for active transactions to complete
        while (activeTransactions.isNotEmpty()) {
            Thread.sleep(50)
        }
        shutdownLatch.countDown()
    }

    fun processPayment(request: PaymentRequest): PaymentResult {
        if (isShuttingDown.get()) {
            return PaymentResult(false, error = "SERVICE_SHUTTING_DOWN")
        }

        val transactionId = generateTransactionId(request)

        // Validate auth token before processing
        if (!validateAuthToken(request)) {
            return PaymentResult(false, error = "INVALID_AUTH")
        }

        // Check for replay attacks
        if (completedTokens.containsKey(request.nonce)) {
            return PaymentResult(false, error = "DUPLICATE_NONCE")
        }

        val state = TransactionState(
            merchantId = request.merchantId,
            amount = request.amount,
            timestamp = System.currentTimeMillis()
        )
        activeTransactions[transactionId] = state

        try {
            // Simulate payment gateway interaction
            val result = executePayment(state)
            completedTokens[request.nonce] = System.currentTimeMillis()
            return PaymentResult(true, transactionId = transactionId)
        } finally {
            activeTransactions.remove(transactionId)
        }
    }

    private fun validateAuthToken(request: PaymentRequest): Boolean {
        val expectedToken = computeHmac(
            "${request.merchantId}:${request.amount}:${request.nonce}"
        )
        return sequenceEqual(request.authToken.toByteArray(), expectedToken)
    }

    /**
     * Constant-time comparison to prevent timing attacks.
     * Compares all bytes regardless of mismatch position.
     */
    private fun sequenceEqual(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false

        var result = 0
        for (i in a.indices) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }

    private fun computeHmac(data: String): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        val keySpec = SecretKeySpec(hmacSecret, "HmacSHA256")
        mac.init(keySpec)
        return mac.doFinal(data.toByteArray(Charsets.UTF_8))
    }

    private fun generateTransactionId(request: PaymentRequest): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val input = "${request.merchantId}:${request.nonce}:${System.nanoTime()}"
        return digest.digest(input.toByteArray()).joinToString("") { "%02x".format(it) }.take(32)
    }

    private fun executePayment(state: TransactionState): Boolean {
        // Simulate processing delay proportional to risk scoring
        val riskDelay = when {
            state.amount > 10000 -> 200L
            state.amount > 1000 -> 100L
            else -> 50L
        }
        Thread.sleep(riskDelay)
        return true
    }

    fun getActiveTransactionCount(): Int = activeTransactions.size

    fun awaitShutdown() {
        shutdownLatch.await()
    }
}
